pub(crate) fn get_syntax_for(&self, path: impl AsRef<Path>) -> Option<MappingTarget<'a>> {
    let path = path.as_ref();

    let candidate = Candidate::new(path);
    let candidate_filename = path.file_name().map(Candidate::new);
    for (ref glob, ref syntax) in self.mappings.iter().rev() {
        if glob.is_match_candidate(&candidate)
            || candidate_filename
                .as_ref()
                .map_or(false, |filename| glob.is_match_candidate(filename))
        {
            return Some(*syntax);
        }
    }

    // If no mapping matched, try again with the ignored suffixes stripped
    // from the file name in order to make `--map-syntax` and
    // `--ignored-suffix` work together (see #2260).
    let file_name = path.file_name()?;
    let parent = path.parent();
    self.ignored_suffixes
        .try_with_stripped_suffix(file_name, |stripped_file_name| {
            let stripped_path = parent.map_or(PathBuf::from(stripped_file_name), |p| {
                p.join(stripped_file_name)
            });
            // Note: recursion
            Ok(self.get_syntax_for(stripped_path))
        })
        .unwrap_or(None)
}

